head.script:
(function () {
  var XHTML_NS =
    "http://www.w3.org/1999/xhtml";

  var foreignObject =
    document.querySelector(
      "foreignObject"
    );

  if (!foreignObject) return;

  var root =
    foreignObject.firstElementChild;

  if (!root) return;

  var origCE =
    document.createElement.bind(
      document
    );

  var origCENS =
    document.createElementNS.bind(
      document
    );

  try {
    Object.defineProperty(
      document,
      "head",
      {
        get: function () {
          return root.querySelector(
            "head"
          );
        },
        configurable: true
      }
    );

    Object.defineProperty(
      document,
      "body",
      {
        get: function () {
          return root.querySelector(
            "body"
          );
        },
        configurable: true
      }
    );

    Object.defineProperty(
      document,
      "documentElement",
      {
        get: function () {
          return root;
        },
        configurable: true
      }
    );
  } catch (_) {}

  document.createElement =
    function (tag, options) {
      if (
        typeof tag === "string"
      ) {
        try {
          return origCENS(
            XHTML_NS,
            tag,
            options
          );
        } catch (_) {
          return origCENS(
            XHTML_NS,
            tag
          );
        }
      }

      return origCE(
        tag,
        options
      );
    };

  document.createElementNS =
    function (
      ns,
      tag,
      options
    ) {
      if (
        ns == null ||
        ns === XHTML_NS
      ) {
        try {
          return origCENS(
            XHTML_NS,
            tag,
            options
          );
        } catch (_) {
          return origCENS(
            XHTML_NS,
            tag
          );
        }
      }

      try {
        return origCENS(
          ns,
          tag,
          options
        );
      } catch (_) {
        return origCENS(
          ns,
          tag
        );
      }
    };

  try {
    Object.defineProperty(
      document,
      "getElementById",
      {
        value: function (id) {
          var safe =
            String(id).replace(
              /["\\]/g,
              "\\$&"
            );

          return root.querySelector(
            '[id="' +
            safe +
            '"]'
          );
        },
        configurable: true,
        writable: true
      }
    );
  } catch (_) {}

  try {
    document.getElementsByTagName =
      function (tag) {
        return root
          .getElementsByTagNameNS(
            XHTML_NS,
            tag
          );
      };
  } catch (_) {}

  try {
    document.getElementsByClassName =
      function (name) {
        return root
          .getElementsByClassName(
            name
          );
      };
  } catch (_) {}

  var origQS =
    document.querySelector.bind(
      document
    );

  var origQSA =
    document.querySelectorAll.bind(
      document
    );

  document.querySelector =
    function (selector) {
      try {
        return (
          root.querySelector(
            selector
          ) ||
          origQS(selector)
        );
      } catch (_) {
        return origQS(selector);
      }
    };

  document.querySelectorAll =
    function (selector) {
      try {
        var result =
          root.querySelectorAll(
            selector
          );

        return result.length
          ? result
          : origQSA(selector);
      } catch (_) {
        return origQSA(selector);
      }
    };
})();

body.script:
(function () {
  var url =
    new URL(
      "./assets/bundle.js",
      window.location.href
    ).href;

  import(url).catch(
    function (error) {
      console.error(
        "[synnical-svg] application boot failed",
        error
      );

      try {
        var root =
          document.getElementById(
            "root"
          );

        if (root) {
          root.innerHTML =
            '<div style="' +
            'box-sizing:border-box;' +
            'padding:24px;' +
            'font:14px monospace;' +
            'color:#ff8b8b;' +
            'background:#050505;' +
            'width:100%;' +
            'height:100%' +
            '">' +
            '<b>Synnical failed to start.</b><br />' +
            String(
              error &&
              (
                error.message ||
                error
              )
            ) +
            '</div>';
        }
      } catch (_) {}
    }
  );
})();
